# ------------------------------------------------------------------ the ring as a "road" for the world helpers
class Ring:
    """Duck-types world.Road for terrain(), ground_z() and flora.vegetation(): distance to the track, flat inside."""
    def __init__(self, r):
        self.r = r

    def nearest(self, x, y):
        # +30 m: the terrain's field patchwork starts right at the outer verge (no soft grass halo round the ring)
        rr = math.hypot(x, y)
        d = max(0.0, rr - self.r) + 30.0
        return math.atan2(y, x) * self.r, d, 0.55       # ground_z: base = rz - 0.8 = -0.25 near the track


RING = Ring(R + PAVED + BANKETT)


def annulus(name, r0, r1, mat, c, z0=0.0, z1=None, seg=720, u0=None):
    """Flat or sloped ring band between radii r0 and r1. UV u = lateral metres (u0 at r0), v = arc length."""
    z1 = z0 if z1 is None else z1
    verts, faces, uvs = [], [], []
    for k in range(seg + 1):
        th = 2 * math.pi * k / seg
        c_, s_ = math.cos(th), math.sin(th)
        verts += [(r0 * c_, r0 * s_, z0), (r1 * c_, r1 * s_, z1)]
        uu = (u0 if u0 is not None else r0)
        uvs += [(uu, R * th), (uu + (r1 - r0), R * th)]
        if k:
            b = 2 * (k - 1)
            faces.append((b, b + 1, b + 3, b + 2))
    return W.mesh_obj(name, verts, faces, mat, c, uvs)


def disc_mesh(name, r, mat, c, z=0.0, seg=180):
    verts = [(0.0, 0.0, z)] + [(r * math.cos(2 * math.pi * k / seg), r * math.sin(2 * math.pi * k / seg), z)
                               for k in range(seg)]
    faces = [(0, 1 + k, 1 + (k + 1) % seg) for k in range(seg)]
    return W.mesh_obj(name, verts, faces, mat, c)


