def crops_mat():
    """The infield is farmland (October): plots of about 30 m (winter wheat with tramlines, ploughed soil, stubble,
    maize stubble, fallow), drill rows 2 m apart, so the top shots have texture and scale."""
    m = bpy.data.materials.new("infield_crops")
    m.use_nodes = True
    nt = m.node_tree
    p = nt.nodes["Principled BSDF"]
    p.inputs["Roughness"].default_value = 0.92
    L = nt.links
    tc = nt.nodes.new("ShaderNodeTexCoord")
    vor = nt.nodes.new("ShaderNodeTexVoronoi")
    vor.voronoi_dimensions = "2D"
    vor.distance = "CHEBYCHEV"
    vor.inputs["Scale"].default_value = 1.0
    vor.inputs["Randomness"].default_value = 0.8
    mp = nt.nodes.new("ShaderNodeMapping")
    mp.inputs["Scale"].default_value = (1 / 34.0, 1 / 26.0, 1.0)
    mp.inputs["Rotation"].default_value = (0, 0, 0.3)
    L.new(tc.outputs["Object"], mp.inputs["Vector"])
    L.new(mp.outputs["Vector"], vor.inputs["Vector"])
    sep = nt.nodes.new("ShaderNodeSeparateColor")
    L.new(vor.outputs["Color"], sep.inputs["Color"])
    ramp = nt.nodes.new("ShaderNodeValToRGB")
    ramp.color_ramp.interpolation = "CONSTANT"
    cols = [(0.0, (0.2, 0.12, 0.06)), (0.2, (0.5, 0.42, 0.22)), (0.4, (0.13, 0.3, 0.05)), (0.6, (0.42, 0.33, 0.16)),
            (0.8, (0.18, 0.34, 0.07))]
    ramp.color_ramp.elements[0].position, ramp.color_ramp.elements[0].color = cols[0][0], (*cols[0][1], 1)
    ramp.color_ramp.elements[1].position, ramp.color_ramp.elements[1].color = cols[1][0], (*cols[1][1], 1)
    for pos, col in cols[2:]:
        ramp.color_ramp.elements.new(pos).color = (*col, 1)
    L.new(sep.outputs[0], ramp.inputs["Fac"])
    wave = nt.nodes.new("ShaderNodeTexWave")
    wave.inputs["Scale"].default_value = 0.5
    wave.inputs["Distortion"].default_value = 0.6
    L.new(tc.outputs["Object"], wave.inputs["Vector"])
    rows = nt.nodes.new("ShaderNodeMix")
    rows.data_type = "RGBA"
    rows.blend_type = "MULTIPLY"
    rows.inputs["Factor"].default_value = 0.28
    L.new(ramp.outputs["Color"], rows.inputs["A"])
    L.new(wave.outputs["Color"], rows.inputs["B"])
    nz = nt.nodes.new("ShaderNodeTexNoise")
    nz.inputs["Scale"].default_value = 0.4
    L.new(tc.outputs["Object"], nz.inputs["Vector"])
    nmix = nt.nodes.new("ShaderNodeMix")
    nmix.data_type = "RGBA"
    nmix.blend_type = "OVERLAY"
    nmix.inputs["Factor"].default_value = 0.25
    L.new(rows.outputs["Result"], nmix.inputs["A"])
    L.new(nz.outputs["Color"], nmix.inputs["B"])
    L.new(nmix.outputs["Result"], p.inputs["Base Color"])
    return m


def infield_mat():
    """Mown grass of the infield: the world.py grass with mowing stripes 6 m wide (scale for the top shots)."""
    m = W.noisy("infield_grass", (0.12, 0.27, 0.05), (0.22, 0.4, 0.09), 0.15, rough=0.9, detail=5)
    nt = m.node_tree
    p = nt.nodes["Principled BSDF"]
    src_ = p.inputs["Base Color"].links[0].from_socket
    tc = nt.nodes.new("ShaderNodeTexCoord")
    sep = nt.nodes.new("ShaderNodeSeparateXYZ")
    nt.links.new(tc.outputs["Object"], sep.inputs[0])
    mul = nt.nodes.new("ShaderNodeMath")
    mul.operation = "MULTIPLY"
    mul.inputs[1].default_value = math.pi / 6.0
    nt.links.new(sep.outputs["X"], mul.inputs[0])
    sn = nt.nodes.new("ShaderNodeMath")
    sn.operation = "SINE"
    nt.links.new(mul.outputs[0], sn.inputs[0])
    gt = nt.nodes.new("ShaderNodeMath")
    gt.operation = "GREATER_THAN"
    gt.inputs[1].default_value = 0.0
    nt.links.new(sn.outputs[0], gt.inputs[0])
    mx = nt.nodes.new("ShaderNodeMix")
    mx.data_type = "RGBA"
    mx.blend_type = "MULTIPLY"
    mx.inputs["B"].default_value = (0.82, 0.86, 0.8, 1)
    nt.links.new(gt.outputs[0], mx.inputs["Factor"])
    nt.links.new(src_, mx.inputs["A"])
    nt.links.new(mx.outputs["Result"], p.inputs["Base Color"])
    return m
