def leitpfosten_left(c):
    """Zeichen 620 for the left side of the road: same 1.0 m triangular post, top slanted towards the road (local +x),
    25 cm black band, two small round white reflectors one above the other."""
    tri = [(-0.06, -0.035), (0.06, -0.035), (0.0, 0.07)]

    def top(x):
        return 0.96 - (x / 0.06) * 0.04

    root = bpy.data.collections.new("leitpfosten_left")
    c.children.link(root)

    def prism(name, z0f, z1f, mat, k=1.0):
        verts = [(x * k, y * k, z0f(x)) for x, y in tri] + [(x * k, y * k, z1f(x)) for x, y in tri]
        faces = [(2, 1, 0), (3, 4, 5), (0, 1, 4, 3), (1, 2, 5, 4), (2, 0, 3, 5)]
        return W.mesh_obj(name, verts, faces, mat, root)

    prism("lpl_body", lambda x: 0.0, top, M.white)
    prism("lpl_band", lambda x: top(x) - 0.31, lambda x: top(x) - 0.06, M.black, 1.03)
    for k, z in enumerate((0.745, 0.815)):
        verts = [(0.018 * math.cos(2 * math.pi * j / 16), -0.0375, z + 0.018 * math.sin(2 * math.pi * j / 16))
                 for j in range(16)]
        W.mesh_obj(f"lpl_refl{k}", verts, [tuple(range(16))], M.refl, root)
    return root


