def wheel_hubs(car):
    """Put every tyre and its rim under one hub empty at the axle centre, so the hub can spin (rotation about x)."""
    g = car["coll"].objects[car["name"]]
    tyres = [o for o in car["coll"].objects if o.type == "MESH" and o.data.materials
             and o.data.materials[0].name.startswith("car_tyre")]
    rims = [o for o in car["coll"].objects if o.type == "MESH" and o.data.materials
            and o.data.materials[0].name.startswith("car_rim")]
    hubs = []
    for t in tyres:
        c0 = t.location.copy()
        hub = bpy.data.objects.new(car["name"] + "_hub", None)
        car["coll"].objects.link(hub)
        hub.parent = g
        hub.location = c0
        hub.rotation_mode = "XYZ"
        for o in [t] + [r_ for r_ in rims if abs(r_.location.y - c0.y) < 0.2 and r_.location.x * c0.x > 0]:
            o.parent = hub
            o.matrix_parent_inverse.identity()
            o.location = o.location - c0 if o is not t else Vector((0, 0, 0))
        hubs.append(dict(obj=hub, r=max(t.dimensions.x, t.dimensions.y) / 2, front=c0.y > 0))
    return hubs


frames = list(range(1, N + 1))
cuts = set(D["cuts"])
for i, car in enumerate(cars):
    s_ = D["cars"]["s"][i]
    locs, rots = [], []
    for s in s_:
        th = s / R
        locs.append((R * math.cos(th), R * math.sin(th), Z_ROAD))
        rots.append((0.0, 0.0, th))
    stage.bake_motion(car["obj"], frames, locs, rots)
    car["track"] = locs
    for hb in wheel_hubs(car):
        spin = [(-s / hb["r"], 0.0, (math.atan(2.7 / R) if hb["front"] else 0.0)) for s in s_]
        hl = [tuple(hb["obj"].location)] * N
        stage.bake_motion(hb["obj"], frames, hl, spin)
    br = D["cars"]["brake"][i]
    pairs, last = [], None
    for f, b in zip(frames, br):
        if b != last:
            pairs.append((f, 8.0 if b else 0.8))
            last = b
    jx.key_emission(car["tail"], pairs)


