def chip_mat(name):
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    p = m.node_tree.nodes["Principled BSDF"]
    p.inputs["Roughness"].default_value = 0.35
    p.inputs["Emission Strength"].default_value = 1.6
    return m


chip_mats = []
for i, car in enumerate(cars):
    m = chip_mat(f"chip{i:02d}")
    chip_mats.append(m)
    bpy.ops.mesh.primitive_uv_sphere_add(segments=24, ring_count=12, radius=0.85)
    o = W.link(bpy.context.active_object, traffic)
    o.name = f"chip{i:02d}"
    o.scale = (1.0, 1.0, 0.42)
    bpy.ops.object.shade_smooth()
    o.data.materials.append(m)
    o.visible_shadow = False
    o.parent = car["obj"]
    o.location = (0.0, 0.0, car["roof"] + 1.15)
    p = m.node_tree.nodes["Principled BSDF"]
    states = D["cars"]["chip"][i]
    last = None
    for f, st in zip(frames, states):
        k = 0.0 if st == 0 else CHIP_SCALE.get(D["shot"][f - 1], 1.0)
        if (st, k) != last:
            col = CHIP_COL.get(st, (0.5, 0.5, 0.5))
            p.inputs["Base Color"].default_value = (*col, 1)
            p.inputs["Emission Color"].default_value = (*col, 1)
            p.inputs["Base Color"].keyframe_insert("default_value", frame=f)
            p.inputs["Emission Color"].keyframe_insert("default_value", frame=f)
            o.scale = (k, k, 0.42 * k)
            o.keyframe_insert("scale", frame=f)
            last = (st, k)
    for idb in (m.node_tree, o):
        for fc in stage.fcurves(idb):
            for kp in fc.keyframe_points:
                kp.interpolation = "CONSTANT"


# ------------------------------------------------------------------ the jam band (red, on the road under the jam)
def band_material():
    m = bpy.data.materials.new("jam_band")
    m.use_nodes = True
    nt = m.node_tree
    for n_ in list(nt.nodes):
        if n_.type != "OUTPUT_MATERIAL":
            nt.nodes.remove(n_)
    L = nt.links

    def node(t, **kw):
        n_ = nt.nodes.new(t)
        for k, v in kw.items():
            setattr(n_, k, v)
        return n_

    def math_(op, a_, b_=None, c_=None):
        n_ = node("ShaderNodeMath", operation=op)
        for k, v in enumerate((a_, b_, c_)):
            if v is None:
                continue
            if isinstance(v, (int, float)):
                n_.inputs[k].default_value = v
            else:
                L.new(v, n_.inputs[k])
        return n_.outputs[0]

    tc = node("ShaderNodeTexCoord")
    sep = node("ShaderNodeSeparateXYZ")
    L.new(tc.outputs["Object"], sep.inputs[0])
    ang = math_("ARCTAN2", sep.outputs["Y"], sep.outputs["X"])
    start = node("ShaderNodeValue", label="start")
    length = node("ShaderNodeValue", label="length")
    stren = node("ShaderNodeValue", label="strength")
    start.name, length.name, stren.name = "start", "length", "strength"
    rel = math_("FLOORED_MODULO", math_("SUBTRACT", ang, start.outputs[0]), 2 * math.pi)
    soft = 2.5 / R
    m_in = math_("MINIMUM", math_("DIVIDE", rel, soft), 1.0)
    m_out = math_("MINIMUM", math_("DIVIDE", math_("SUBTRACT", length.outputs[0], rel), soft), 1.0)
    mask = math_("MAXIMUM", math_("MINIMUM", m_in, m_out), 0.0)
    alpha = math_("MULTIPLY", math_("MULTIPLY", mask, stren.outputs[0]), 0.72)
    em = node("ShaderNodeEmission")
    em.inputs["Color"].default_value = (1.0, 0.07, 0.03, 1)
    em.inputs["Strength"].default_value = 3.4
    tr = node("ShaderNodeBsdfTransparent")
    mx = node("ShaderNodeMixShader")
    L.new(alpha, mx.inputs[0])
    L.new(tr.outputs[0], mx.inputs[1])
    L.new(em.outputs[0], mx.inputs[2])
    L.new(mx.outputs[0], nt.nodes["Material Output"].inputs["Surface"])
    return m, start, length, stren


band_m, b_start, b_len, b_str = band_material()
band = annulus("jam_band_mesh", R - 2.6, R + 2.6, band_m, env, Z_ROAD + 0.03)
band.visible_shadow = False
prev_strength = None
for f, (st, ln, strength) in zip(frames, D["band"]):
    b_start.outputs[0].default_value = st
    b_len.outputs[0].default_value = ln
    b_start.outputs[0].keyframe_insert("default_value", frame=f)
    b_len.outputs[0].keyframe_insert("default_value", frame=f)
    if strength != prev_strength:
        b_str.outputs[0].default_value = strength
        b_str.outputs[0].keyframe_insert("default_value", frame=f)
        prev_strength = strength
for fc in stage.fcurves(band_m.node_tree):
    if "strength" in fc.data_path:
        for kp in fc.keyframe_points:
            kp.interpolation = "CONSTANT"

# ------------------------------------------------------------------ arrows: cars forwards, the jam backwards
arrow_r = W.principled("trackc_arrow_red", (1.0, 0.08, 0.03), 0.5, emit=(1.0, 0.07, 0.03), estr=2.2)
arrow_w = W.principled("trackc_arrow_white", (0.95, 0.95, 0.95), 0.5, emit=(1.0, 1.0, 1.0), estr=1.4)
arrow_k = W.principled("trackc_arrow_line", (0.0, 0.0, 0.0), 0.6)


def arrow(name, scale=1.0, fill=None):
    arrow_y = fill
    pts = [(-1.6, -0.35), (0.4, -0.35), (0.4, -0.9), (1.6, 0.0), (0.4, 0.9), (0.4, 0.35), (-1.6, 0.35)]
    root = bpy.data.objects.new(name, None)
    env.objects.link(root)
    for nm, m, g in ((name + "_fill", arrow_y, 0.0), (name + "_line", arrow_k, 0.18)):
        q = [(x * (1 + g / 1.6) * scale, y * (1 + g / 0.9) * scale, -0.03 if g else 0.0) for x, y in pts]
        o = W.mesh_obj(nm, q, [list(range(len(q)))], m, env)
        o.parent = root
        o.visible_shadow = False
    return root


arr_back = arrow("arrow_back", 4.0, arrow_r)       # the jam: backwards, next to the band
arr_fwd = arrow("arrow_fwd", 3.4, arrow_w)         # the cars: forwards, further inside
la, ra_, lf, rf, sb, sf = [], [], [], [], [], []
on_frames = [f for f, q in zip(frames, D["arrows"]) if q[2] > 0]
f_on = on_frames[0] if on_frames else N + 10
f_off = on_frames[-1] if on_frames else N + 10
for f, (mid, hs, on) in zip(frames, D["arrows"]):
    if on <= 0:
        mid, hs = (D["arrows"][f_on - 1][0], D["arrows"][f_on - 1][1]) if f < f_on else \
            (D["arrows"][f_off - 1][0], D["arrows"][f_off - 1][1])
    th_b, th_f = mid / R, hs / R
    rb, rfw = R - 9.0, R - 19.0                         # both inside the ring, the jam arrow next to the band
    la.append((rb * math.cos(th_b), rb * math.sin(th_b), 3.0))
    ra_.append((0.0, 0.0, th_b - math.pi / 2))          # arrow +x along the backwards tangent
    lf.append((rfw * math.cos(th_f), rfw * math.sin(th_f), 3.0))
    rf.append((0.0, 0.0, th_f + math.pi / 2))           # arrow +x along the driving direction
    k = 0.0
    if f_on <= f <= f_off:
        k = min(1.0, (f - f_on) / 6.0) * (1.12 if f - f_on in (4, 5) else 1.0)
        k = min(k, max(0.0, (f_off - f) / 5.0))
    sb.append((k, k, k))
stage.bake_motion(arr_back, frames, la, ra_)
stage.bake_motion(arr_fwd, frames, lf, rf)
for o in (arr_back, arr_fwd):
    for f, s3 in zip(frames, sb):
        o.scale = s3
        o.keyframe_insert("scale", frame=f)

# ------------------------------------------------------------------ cameras
cams = {}
for name, cd in D["cams"].items():
    co = stage.camera(name, cd["lens"])
    locs, rots = [], []
    for p, q, u_ in zip(cd["pos"], cd["tgt"], cd["up"]):
        locs.append(tuple(p))
        rots.append(tuple(stage.look_rot(Vector(p), Vector(q), Vector(u_) if u_ else None)))
    for k in range(1, len(rots)):
        r_ = list(rots[k])
        for j in range(3):
            while r_[j] - rots[k - 1][j] > math.pi:
                r_[j] -= 2 * math.pi
            while r_[j] - rots[k - 1][j] < -math.pi:
                r_[j] += 2 * math.pi
        rots[k] = tuple(r_)
    stage.bake_motion(co, cd["frames"], locs, rots)
    sc.timeline_markers.new(name, frame=cd["f0"]).camera = co
    cams[name] = co
sc.camera = cams[D["shot"][0]]

# ------------------------------------------------------------------ look and render
stage.sky(None, Vector((0.45, 0.85, 0.0)).normalized(), ASSETS, sun_elev_deg=32.0)
stage.hazify_all(dist=2400.0, skip=("jam_band", "trackc_arrow_red", "trackc_arrow_white", "trackc_arrow_line") +
                 tuple(m.name for m in chip_mats))
stage.render_setup(SAMPLES, RES, int(round(RES * 16 / 9)))
os.makedirs(OUT, exist_ok=True)
todo = STILLS or list(range(FR[0], FR[1] + 1) if FR else range(1, N + 1))
BLUR = sc.render.use_motion_blur and not NOBLUR      # as stage.render_setup / kit/perf.py chose for this profile
for f in todo:
    sc.frame_set(f)
    cam = cams[D["shot"][f - 1]]
    if sc.camera != cam:              # a camera assignment rebuilds the depsgraph relations: only at cuts
        sc.camera = cam
    blur = BLUR and f not in cuts     # no blur on the first and last frame of a shot (cars jump between windows)
    if sc.render.use_motion_blur != blur:
        sc.render.use_motion_blur = blur
    sc.render.filepath = os.path.join(OUT, f"f_{f:04d}.png")
    bpy.ops.render.render(write_still=True)
    print("Saved", sc.render.filepath, flush=True)
print("RENDER_DONE", FR)
